package replicacache

import (
	_ "embed"
	"encoding/json"
	"strings"
	"sync"
)

// filterVocabJSON is NetBox's filter vocabulary: model label -> filter name ->
// the meanings NetBox gives that name, newest NetBox version first. It is
// generated by internal/genfilters from NetBox's own filtersets, introspected
// read-only in NetBox 4.4.10 and 4.6.10 containers, the way choicelabels.json is
// generated from its API schemas. Replica-cache mode accepts a filter exactly
// when NetBox has it, with NetBox's meaning, and this is where NetBox's meaning
// is written down.
//
// It covers every model with an API viewset, not only the ones replica-cache
// v1.40.1 lists, so an entity the replica starts to serve is described already.
// A filter only the newer NetBox has is in it: NetBox 4.4 ignores such a filter
// and returns every row, a replica of 4.4 honours it.
//
//go:embed filtervocab.json
var filterVocabJSON []byte

// The kinds of meaning a NetBox filter has here. What each asks of a caller is
// in its entry's fields, listed at vocabEntry.
const (
	kindValue        = "value"
	kindMAC          = "mac"
	kindBool         = "bool"
	kindIsNull       = "isnull"
	kindEmpty        = "empty"
	kindRelated      = "related"
	kindTree         = "tree"
	kindModelChoice  = "modelchoice"
	kindAddress      = "address"
	kindPrefix       = "prefix"
	kindContains     = "contains"
	kindLocalContext = "localcontext"
	kindMethod       = "method"
	kindPath         = "path"
	kindRefuse       = "refuse"
)

// vocabEntry is one meaning of a NetBox filter on one model. The JSON names are
// short because the file holds one per filter of every model.
//
// Kind says what the filter does; the fields it sets are in brackets.
//
//	value         one local column compared with NetBox's lookup, text, a choice or a number [Column, Lookup, NullValue]
//	mac           the same on a MAC address column, which NetBox normalises [Column, Lookup, NullValue]
//	bool          equality on a boolean column [Column]
//	isnull        a boolean that means IS NULL on Column, IS NOT NULL when Exclude [Column]
//	empty         NetBox's empty lookup on Column: NULL or "" [Column]
//	related       a foreign key, compared by ToField of its Target [Column, ToField, Target, Null]
//	tree          the same, and the descendants of each node are included
//	modelchoice   the same on a single-valued filter
//	address       NetBox's address match on Column (net_in) [Column]
//	prefix        NetBox's prefix match on Column [Column]
//	contains      a prefix's containment search; Column is the prefix [Column]
//	localcontext  whether the local config context is set [Column]
//	method        another filter NetBox computes with a method of its own [Method]
//	path          a filter NetBox applies through other relations: tenant → group [Path]
//	refuse        a filter whose meaning a replica cannot reproduce [Reason]
//
// Two fields do not depend on the kind. Exclude is set on every kind but refuse,
// when NetBox negates the filter (site__n; cabled is an isnull that excludes).
// Single is set on every kind, refusals included (ipam.prefix family is refused
// and single-valued): it follows the filter's class, not what the filter does.
type vocabEntry struct {
	Kind string `json:"k"`
	// Column is the column the filter reads on this model, as Django names it
	// (_site_id for a component's _site, never the filter's name with _id put on
	// the end). It is empty on a path, a method and a refusal.
	Column string `json:"c,omitempty"`
	// Lookup is NetBox's lookup on a value or mac filter: exact, or iexact on the
	// filters NetBox matches without regard to case (devices' name and serial,
	// VMs' name, and the serial of racks, modules and inventory items; a VM's
	// serial is exact), or icontains, gt, ...
	Lookup  string `json:"l,omitempty"`
	Exclude bool   `json:"x,omitempty"`
	// ToField is the field of the target a related, tree or modelchoice filter
	// compares: id, or the slug, name, rd or address NetBox's filter names.
	ToField string `json:"t,omitempty"`
	// Target is the label of the model the foreign key points at (dcim.site).
	Target string `json:"target,omitempty"`
	// Null is true when NetBox's form for the filter takes the literal null, as
	// IS NULL. Cable-terminations' cable takes none; every declared relation does.
	Null bool `json:"null,omitempty"`
	// NullValue (nv) is true when a value or mac filter reads the literal null
	// as IS NULL, measured by compiling <name>=null inside NetBox: text and MAC
	// filters and the choices that have a null choice do; number filters (a 400),
	// the other choices (a 400) and the text searches do not. Sites' time_zone and
	// time_zone__n compare it as the empty string and do not either, while
	// time_zone__ie and time_zone__nie compile to IS NULL and carry it.
	NullValue bool `json:"nv,omitempty"`
	// Single is true when NetBox reads one value, the last of a repeated
	// parameter, where its multi-valued filters take them all.
	Single bool `json:"single,omitempty"`
	// Method is the name of the filterset method of a method entry.
	Method string `json:"m,omitempty"`
	// Path is the walk of a path entry, its parts joined with " → ".
	Path string `json:"p,omitempty"`
	// Reason is why a filter is refused: badempty (an __empty filter whose class
	// is not a boolean, which NetBox answers with a 400), decimal, date,
	// contenttype, array, uuid, wwn, lookup:<lookup> (a lookup the replica has no
	// operator for) or other.
	Reason string `json:"r,omitempty"`
}

// loadVocab decodes the file once, on the first query that needs it, and keys it
// by the replica's table: NetBox's table for a model is its app label and its
// model name joined by an underscore (dcim.device is dcim_device), which is the
// name the catalogue gives each entity. A file that does not decode covers
// nothing, so every filter keeps the catalogue-only rules; the embedded-file test
// is what keeps that from shipping.
var loadVocab = sync.OnceValue(func() map[string]map[string][]vocabEntry {
	var byLabel map[string]map[string][]vocabEntry
	if json.Unmarshal(filterVocabJSON, &byLabel) != nil {
		return nil
	}
	byTable := make(map[string]map[string][]vocabEntry, len(byLabel))
	for label, names := range byLabel {
		byTable[strings.Replace(label, ".", "_", 1)] = names
	}
	return byTable
})

// vocabFor returns NetBox's filters on a replica table, by the name NetBox gives
// them in a query string (site, site__n, name__ic), each with its meanings
// newest NetBox first. False means the vocabulary does not describe the table: a
// plugin's model, or one NetBox has no API viewset for (dcim_cablepath). The
// caller then keeps today's catalogue-only behaviour. The map is shared and must
// not be modified.
func vocabFor(table string) (map[string][]vocabEntry, bool) {
	names, ok := loadVocab()[table]
	return names, ok
}

// pickVocab chooses among a filter's meanings for the replica at hand. A replica
// mirrors one NetBox, and the versions the vocabulary was read from disagree on a
// few filters (front ports' rear_port_id is a column on 4.4 and a join on 4.6),
// so it is the first alternative whose column the entity stores that wins, and
// the first alternative, the newest NetBox's, when none does. An alternative that
// names no column (a path, a method, a refusal) never matches by this, so a
// meaning the replica can use is preferred over one that is refused.
func pickVocab(alts []vocabEntry, e entity) vocabEntry {
	for _, alt := range alts {
		if alt.Column != "" && e.has(alt.Column) {
			return alt
		}
	}
	if len(alts) == 0 {
		return vocabEntry{}
	}
	return alts[0]
}
